  forall (Gamma : Ctx) (inner : CoreTerm) (level : option nat),
    Typing Gamma inner (sortTerm level) ->
    Typing Gamma (Sharp inner) (sortTerm level).
Proof. exact T_sharp. Qed.

(* `Soundness rule` is the propositional shape of the per-rule    *)
(* lemma `K_<rule>_sound`.  Each branch quotes the rule's typing  *)
(* judgement; `kernel_soundness` aggregates them.                 *)
Definition Soundness (rule : KernelRule) : Prop :=
  match rule with
  | K_Var => forall (Gamma : Ctx) (x : string) (T : CoreTerm), lookup Gamma x = Some T -> Typing Gamma (Var x) T
  | K_Univ => forall (Gamma : Ctx) (i : nat), (i < Nat.pow 2 32 - 1)%nat -> Typing Gamma (Universe i) (Universe (S i))
  | K_Pi_Form => forall (Gamma : Ctx) (x : string) (A B : CoreTerm) (i : nat), Typing Gamma A (Universe i) -> Typing ((x, A) :: Gamma) B (Universe i) -> Typing Gamma (Pi x A B) (Universe i)
  | K_Lam_Intro => forall (Gamma : Ctx) (x : string) (A b B : CoreTerm) (i : nat), Typing Gamma A (Universe i) -> Typing ((x, A) :: Gamma) b B -> Typing Gamma (Lam x A b) (Pi x A B)
  | K_App_Elim => forall (Gamma : Ctx) (f a : CoreTerm) (x : string) (A B : CoreTerm), Typing Gamma f (Pi x A B) -> Typing Gamma a A -> Typing Gamma (App f a) (subst x a B)
  | K_Sigma_Form => forall (Gamma : Ctx) (x : string) (A B : CoreTerm) (i : nat), Typing Gamma A (Universe i) -> Typing ((x, A) :: Gamma) B (Universe i) -> Typing Gamma (Sigma x A B) (Universe i)
  | K_Pair_Intro => forall (Gamma : Ctx) (x : string) (A B a b : CoreTerm) (i : nat), Typing Gamma (Sigma x A B) (Universe i) -> Typing Gamma a A -> Typing Gamma b (subst x a B) -> Typing Gamma (Pair a b) (Sigma x A B)
  | K_Fst_Elim => forall (Gamma : Ctx) (p : CoreTerm) (x : string) (A B : CoreTerm), Typing Gamma p (Sigma x A B) -> Typing Gamma (Fst p) A
  | K_Snd_Elim => forall (Gamma : Ctx) (p : CoreTerm) (x : string) (A B : CoreTerm), Typing Gamma p (Sigma x A B) -> Typing Gamma (Snd p) (subst x (Fst p) B)
  | K_Path_Ty_Form => forall (Gamma : Ctx) (A a b : CoreTerm) (i : nat), Typing Gamma A (Universe i) -> Typing Gamma a A -> Typing Gamma b A -> Typing Gamma (PathTy A a b) (Universe i)
  | K_Path_Over_Form => forall (Gamma : Ctx) (motive p lhs rhs carrier start finish : CoreTerm) (x : string) (i : nat), Typing Gamma motive (Pi x carrier (Universe i)) -> Typing Gamma p (PathTy carrier start finish) -> Typing Gamma lhs (App motive start) -> Typing Gamma rhs (App motive finish) -> Typing Gamma (PathOver motive p lhs rhs) (Universe i)
  | K_Refl_Intro => forall (Gamma : Ctx) (a A : CoreTerm), Typing Gamma a A -> Typing Gamma (Refl a) (PathTy A a a)
  | K_Transp => forall (Gamma : Ctx) (path value source target : CoreTerm) (i : nat),     Typing Gamma source (Universe i) ->     Typing Gamma target (Universe i) ->     Typing Gamma path (PathTy (Universe i) source target) ->     Typing Gamma value source ->     Typing Gamma (Transport path value) target
  | K_Refine => forall (Gamma : Ctx) (base predicate : CoreTerm) (x : string) (i : nat), Typing Gamma base (Universe i) -> Typing ((x, base) :: Gamma) predicate PropSort ->     m_depth predicate <= m_depth base -> Typing Gamma (Refine base x predicate) (Universe i)
  | K_Refine_Intro => forall (Gamma : Ctx) (a base predicate witness : CoreTerm) (x : string) (i : nat), Typing Gamma (Refine base x predicate) (Universe i) -> Typing Gamma a base -> Typing Gamma witness (subst x a predicate) -> Typing Gamma a (Refine base x predicate)
  | K_Refine_Erase => forall (Gamma : Ctx) (a base : CoreTerm) (x : string) (predicate : CoreTerm), Typing Gamma a (Refine base x predicate) -> Typing Gamma a base
  | K_Quot_Form => forall (Gamma : Ctx) (base equiv : CoreTerm) (i j : nat),     QuotientFresh "x" [base] ->     Typing Gamma base (Universe i) ->     Typing Gamma equiv (Pi "x" base (Pi "y" base (Universe j))) ->     Typing Gamma (Quotient base equiv) (Universe (Nat.max i j))
  | K_Quot_Intro => forall (Gamma : Ctx) (value base equiv : CoreTerm) (i : nat),     Typing Gamma (Quotient base equiv) (Universe i) ->     Typing Gamma value base ->     Typing Gamma (QuotIntro value base equiv) (Quotient base equiv)
  | K_Quot_Elim => forall (Gamma : Ctx) (scrutinee motive case_fn respect base equiv result : CoreTerm) (i j : nat),     QuotientFresh "q" [result] ->     QuotientFresh "x" [base; equiv; result; case_fn] ->     QuotientFresh "y" [base; equiv; result; case_fn] ->     QuotientFresh "r" [base; equiv; result; case_fn] ->     motive = Lam "q" (Quotient base equiv) result ->     Typing Gamma (Quotient base equiv) (Universe j) ->     Typing Gamma result (Universe i) ->     Typing Gamma scrutinee (Quotient base equiv) ->     Typing Gamma case_fn (Pi "x" base result) ->     Typing Gamma respect (Pi "x" base (Pi "y" base (Pi "r"       (App (App equiv (Var "x")) (Var "y"))       (PathTy result (App case_fn (Var "x")) (App case_fn (Var "y")))))) ->     Typing Gamma (QuotElim scrutinee motive case_fn respect) (App motive scrutinee)
  | K_Universe_Ascent => forall (Gamma : Ctx) (i : nat), (i < Nat.pow 2 32 - 1)%nat -> Typing Gamma (Universe i) (Universe (S i))
  | K_Epsilon_Of => forall (Gamma : Ctx) (articulation result : CoreTerm), Typing Gamma articulation result -> Typing Gamma (EpsilonOf articulation) result
  | K_Alpha_Of => forall (Gamma : Ctx) (enactment result : CoreTerm), Typing Gamma enactment result -> Typing Gamma (AlphaOf enactment) result
  | K_Modal_Box => forall (Gamma : Ctx) (inner T : CoreTerm), Typing Gamma inner T -> Typing Gamma (ModalBox inner) PropSort
  | K_Modal_Diamond => forall (Gamma : Ctx) (inner T : CoreTerm), Typing Gamma inner T -> Typing Gamma (ModalDiamond inner) PropSort
  | K_Modal_Big_And => forall (Gamma : Ctx) (components : list CoreTerm) (typeOf : CoreTerm -> CoreTerm), (forall component, In component components -> Typing Gamma component (typeOf component)) -> Typing Gamma (ModalBigAnd components) PropSort
  | K_Shape => forall (Gamma : Ctx) (inner : CoreTerm) (level : option nat), Typing Gamma inner (sortTerm level) -> Typing Gamma (Shape inner) (sortTerm level)
  | K_Flat => forall (Gamma : Ctx) (inner : CoreTerm) (level : option nat), Typing Gamma inner (sortTerm level) -> Typing Gamma (Flat inner) (sortTerm level)
  | K_Sharp => forall (Gamma : Ctx) (inner : CoreTerm) (level : option nat), Typing Gamma inner (sortTerm level) -> Typing Gamma (Sharp inner) (sortTerm level)
  end.

(* **Kernel soundness** — case-analyses on `KernelRule` and *)
(* dispatches each branch to its `K_<rule>_sound` lemma.    *)
Theorem kernel_soundness : forall rule : KernelRule, Soundness rule.
Proof.
  intro rule. destruct rule.
  - exact K_Var_sound.
  - exact K_Univ_sound.
  - exact K_Pi_Form_sound.
  - exact K_Lam_Intro_sound.
  - exact K_App_Elim_sound.
  - exact K_Sigma_Form_sound.
  - exact K_Pair_Intro_sound.
  - exact K_Fst_Elim_sound.
  - exact K_Snd_Elim_sound.
  - exact K_Path_Ty_Form_sound.
  - exact K_Path_Over_Form_sound.
  - exact K_Refl_Intro_sound.
  - exact K_Transp_sound.
  - exact K_Refine_sound.
  - exact K_Refine_Intro_sound.
  - exact K_Refine_Erase_sound.
  - exact K_Quot_Form_sound.
  - exact K_Quot_Intro_sound.
  - exact K_Quot_Elim_sound.
  - exact K_Universe_Ascent_sound.
  - exact K_Epsilon_Of_sound.
  - exact K_Alpha_Of_sound.
  - exact K_Modal_Box_sound.
  - exact K_Modal_Diamond_sound.
  - exact K_Modal_Big_And_sound.
  - exact K_Shape_sound.
  - exact K_Flat_sound.
  - exact K_Sharp_sound.
Qed.


